//! Image embedding and sizing, verified by walking the PDF content streams with lopdf
//! (independent of the renderer): each image XObject's pixel size and the box it is drawn in.

use angelito_pdf::{RenderOptions, render};
use lopdf::{Document, Object, content::Content};

/// 4x4 PNG.
const PNG_4X4: &str = "iVBORw0KGgoAAAANSUhEUgAAAAQAAAAECAIAAAAmkwkpAAAAEElEQVR4nGM4wcAARwzEcQBRwwyB7RhOggAAAABJRU5ErkJggg==";
/// 30x20 baseline JPEG.
const JPEG_30X20: &str = "";
/// 8x6 GIF.
const GIF_8X6: &str = "R0lGODdhCAAGAIEAAMgeHgAAAAAAAAAAACwAAAAACAAGAAAIDgABCBxIsKDBgwgTDgwIADs=";

/// 8000x6000 1-bit PNG, 5.9 KB compressed: 48 megapixels once decoded (decompression bomb).
const PNG_BOMB_48MP: &str = "";

/// 100x75 1-bit PNG from the same encoder as the bomb.
const PNG_1BIT_100X75: &str = "iVBORw0KGgoAAAANSUhEUgAAAGQAAABLAQAAAACuYx8aAAAAEklEQVR42mNgGAWjYBSMAnQAAAQaAAGJGrelAAAAAElFTkSuQmCC";

/// One drawn image: XObject pixel size and the drawn box (CTM scale) in points.
#[derive(Debug)]
struct Drawn {
    px: (i64, i64),
    pt: (f32, f32),
}

type Matrix = [f32; 6];

fn mul(m: Matrix, n: Matrix) -> Matrix {
    [
        m[0] * n[0] + m[1] * n[2],
        m[0] * n[1] + m[1] * n[3],
        m[2] * n[0] + m[3] * n[2],
        m[2] * n[1] + m[3] * n[3],
        m[4] * n[0] + m[5] * n[2] + n[4],
        m[4] * n[1] + m[5] * n[3] + n[5],
    ]
}

fn num(o: &Object) -> f32 {
    o.as_float().unwrap_or_else(|_| o.as_i64().unwrap() as f32)
}

/// Follow `q`/`Q`/`cm`/`Do` through page content and nested Form XObjects.
fn walk(doc: &Document, content: &[u8], resources: &lopdf::Dictionary, ctm: Matrix, out: &mut Vec<Drawn>) {
    let xobjects = resources.get(b"XObject").ok().and_then(|o| doc.dereference(o).ok()).and_then(|(_, o)| o.as_dict().ok().cloned());
    let (mut ctm, mut stack) = (ctm, Vec::new());
    for op in Content::decode(content).unwrap().operations {
        match op.operator.as_str() {
            "q" => stack.push(ctm),
            "Q" => ctm = stack.pop().unwrap(),
            "cm" => {
                let m: Vec<f32> = op.operands.iter().map(num).collect();
                ctm = mul(m.try_into().unwrap(), ctm);
            }
            "Do" => {
                let name = op.operands[0].as_name().unwrap();
                let id = xobjects.as_ref().unwrap().get(name).unwrap().as_reference().unwrap();
                let s = doc.get_object(id).unwrap().as_stream().unwrap();
                match s.dict.get(b"Subtype").unwrap().as_name().unwrap() {
                    b"Image" => out.push(Drawn {
                        px: (s.dict.get(b"Width").unwrap().as_i64().unwrap(), s.dict.get(b"Height").unwrap().as_i64().unwrap()),
                        pt: (ctm[0].hypot(ctm[1]), ctm[2].hypot(ctm[3])),
                    }),
                    _ => {
                        let m: Matrix = s.dict.get(b"Matrix").ok().and_then(|a| a.as_array().ok()).map_or([1., 0., 0., 1., 0., 0.], |a| {
                            a.iter().map(num).collect::<Vec<_>>().try_into().unwrap()
                        });
                        let res = s.dict.get(b"Resources").ok().and_then(|o| doc.dereference(o).ok()).and_then(|(_, o)| o.as_dict().ok().cloned()).unwrap_or_default();
                        walk(doc, &s.decompressed_content().unwrap_or_else(|_| s.content.clone()), &res, mul(m, ctm), out);
                    }
                }
            }
            _ => {}
        }
    }
}

fn drawn_images(html: &str, opts: &RenderOptions) -> Vec<Drawn> {
    let pdf = render(html, opts).unwrap();
    let doc = Document::load_mem(&pdf).unwrap();
    let mut out = Vec::new();
    for (_, page) in doc.get_pages() {
        let (res, ids) = doc.get_page_resources(page).unwrap();
        let res = res.cloned().unwrap_or_else(|| doc.get_dictionary(ids[0]).unwrap().clone());
        walk(&doc, &doc.get_page_content(page), &res, [1., 0., 0., 1., 0., 0.], &mut out);
    }
    out
}

fn img(mime: &str, b64: &str, style: &str) -> String {
    format!(r#"<img style="{style}" src="data:{mime};base64,{b64}">"#)
}

fn assert_box(d: &Drawn, px: (i64, i64), pt: (f32, f32)) {
    assert_eq!(d.px, px, "{d:?}");
    assert!((d.pt.0 - pt.0).abs() < 0.1 && (d.pt.1 - pt.1).abs() < 0.1, "expected {pt:?} pt, got {d:?}");
}

#[test]
fn data_uri_raster_formats_are_embedded() {
    let o = RenderOptions::default();
    let d = drawn_images(&img("image/png", PNG_4X4, "width:40px;height:40px"), &o);
    assert_eq!(d.len(), 1);
    assert_box(&d[0], (4, 4), (30.0, 30.0));
    let d = drawn_images(&img("image/jpeg", JPEG_30X20, "width:60px;height:20px"), &o);
    assert_eq!(d.len(), 1);
    assert_box(&d[0], (30, 20), (45.0, 15.0));
    let d = drawn_images(&img("image/gif", GIF_8X6, "width:16px;height:12px"), &o);
    assert_eq!(d.len(), 1);
    assert_box(&d[0], (8, 6), (12.0, 9.0));
}

#[test]
fn natural_size_and_aspect_ratio() {
    let o = RenderOptions::default();
    // No width/height: intrinsic pixels, 1 CSS px = 0.75 pt.
    let d = drawn_images(&img("image/jpeg", JPEG_30X20, ""), &o);
    assert_eq!(d.len(), 1);
    assert_box(&d[0], (30, 20), (22.5, 15.0));
    // Width only: height follows the 3:2 ratio.
    let d = drawn_images(&img("image/jpeg", JPEG_30X20, "width:120px"), &o);
    assert_box(&d[0], (30, 20), (90.0, 60.0));
    // Height only (HTML attribute): width follows the ratio.
    let d = drawn_images(&format!(r#"<img height="40" src="data:image/jpeg;base64,{JPEG_30X20}">"#), &o);
    assert_box(&d[0], (30, 20), (45.0, 30.0));
}

#[test]
fn data_uri_svg_is_drawn_as_vector() {
    let svg = r##"<svg xmlns="http://www.w3.org/2000/svg" width="50" height="25"><rect width="50" height="25" fill="#00ff00"/></svg>"##;
    let html = format!(r#"<img src="data:image/svg+xml,{}">"#, svg.replace('#', "%23").replace('"', "'"));
    let pdf = render(&html, &RenderOptions::default()).unwrap();
    let doc = Document::load_mem(&pdf).unwrap();
    // Vector output: green fill operator somewhere in the page content or its Form XObjects.
    let green = doc.objects.values().filter_map(|o| o.as_stream().ok()).any(|s| {
        let c = s.decompressed_content().unwrap_or_else(|_| s.content.clone());
        Content::decode(&c).is_ok_and(|c| {
            c.operations.iter().any(|op| op.operator == "rg" && op.operands.iter().map(num).collect::<Vec<_>>() == [0.0, 1.0, 0.0])
        })
    });
    assert!(green, "SVG rect fill not found");
    assert!(drawn_images(&html, &RenderOptions::default()).is_empty(), "SVG must not be rasterised");
}

#[test]
fn malformed_or_foreign_data_uris_are_ignored() {
    let o = RenderOptions::default();
    for src in ["data:image/png;base64,!!!!", "data:text/plain,hello", "data:image/png;base64,"] {
        assert!(drawn_images(&format!(r#"<p>x</p><img src="{src}">"#), &o).is_empty(), "{src}");
    }
}

#[test]
fn data_uri_decompression_bomb_is_not_embedded() {
    let o = RenderOptions::default();
    assert!(drawn_images(&img("image/png", PNG_BOMB_48MP, "width:10px;height:10px"), &o).is_empty());
    // Same encoder and pixel format, within the 40 MP cap: embedded.
    let d = drawn_images(&img("image/png", PNG_1BIT_100X75, "width:10px;height:10px"), &o);
    assert_eq!(d.len(), 1);
    assert_eq!(d[0].px, (100, 75));
}

#[test]
fn data_uri_size_cap() {
    // Base64 ignores whitespace: same image, larger URL.
    let padded = |mib: usize| {
        let b64 = PNG_4X4.replace("==", &format!("{}==", " ".repeat(mib << 20)));
        img("image/png", &b64, "width:10px;height:10px")
    };
    let o = RenderOptions { max_input_bytes: 64 << 20, ..Default::default() };
    assert_eq!(drawn_images(&padded(31), &o).len(), 1, "31 MiB data: URL is embedded");
    assert!(drawn_images(&padded(33), &o).is_empty(), "data: URL over 32 MiB must be dropped");
}

#[test]
fn data_uri_stylesheet_applies_without_base_dir() {
    let html = r#"<link rel="stylesheet" href="data:text/css,.x%7Bdisplay:none%7D"><p class="x">OCULTO</p><p>VISIBLE</p>"#;
    let doc = Document::load_mem(&render(html, &RenderOptions::default()).unwrap()).unwrap();
    let text = doc.extract_text(&[1]).unwrap();
    assert!(text.contains("VISIBLE") && !text.contains("OCULTO"), "{text:?}");
}
